fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    // Requires: The width must be non-negative and the original vector must be of valid length.
    // Ensures: The returned vector has a length of at least `width` and contains the original characters right-aligned.
    // Invariant: The length of the result is always equal to `width`.
    // Decreases: The difference between `width` and the length of `orig` when `orig_length < target_width`.

    let target_width = width as usize; // Convert u8 to usize for indexing
    let orig_length = orig.len();

    // Ensure that the width is non-negative
    assert!(width >= 0);

    if orig_length >= target_width {
        // If the original length is greater than or equal to the target width, return it unchanged
        // Ensures: The returned vector is equal to `orig`
        return orig;
    } else {
        // Create a new vector with the target width, filled with the fill character
        let mut result = vec![fillchar; target_width];
        // Copy the original sequence to the end of the result vector
        let start_index = target_width - orig_length;
        
        // Ensure: The start index is valid
        assert!(start_index <= target_width);
        
        result[start_index..].copy_from_slice(&orig);
        
        // Ensure: The result has the correct length and is right-justified
        assert_eq!(result.len(), target_width);
        assert_eq!(&result[start_index..], &orig[..]);
        
        result
    }
}

fn main() {
    // Example usage
    let original = vec!['H', 'e', 'l', 'l', 'o'];
    let width = 10;
    let fillchar = ' ';
    let justified = rjust(original, width, fillchar);
    println!("{:?}", justified); // Output: [' ', ' ', ' ', ' ', ' ', ' ', 'H', 'e', 'l', 'l', 'o']
}